import java.util.Scanner;

public class bubblestrike {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int total = sc.nextInt();
        double probability = sc.nextDouble();
        int currentPos = total;
        for (int stepSize = total; stepSize > 0; stepSize /= 2) {
            while (currentPos - stepSize >= 0 && check(currentPos - stepSize, total - (currentPos - stepSize), probability)) {
                currentPos -= stepSize;
            }
        }
        System.out.println(currentPos);
        sc.close();
    }

    public static boolean check(int good, int bad, double p) {
        double g = good;
        double b = bad;
        double numerator = (0.25 * b * Math.max(0, b - 1) * g
                + (g * (Math.max(0, g - 1) * Math.max(0, g - 2) / 6.0) + b * 0.5 * g * Math.max(0, g - 1)));
        double denominator = (g + b) * Math.max(0, g + b - 1) * Math.max(0, g + b - 2) / 6.0;
        double result = numerator / denominator;
        return result >= p;
    }
}
